<?php
namespace App\Http\Controllers;
use App\Models\{User,Workspace}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Log; use Laravel\Socialite\Facades\Socialite;
class AuthController extends Controller {
 public function register(Request $r){$d=$r->validate(['name'=>'required|string|max:255','email'=>'required|email|unique:users','password'=>'required|string|min:8|confirmed']);$u=User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password'])]);$w=Workspace::create(['name'=>$u->name."'s Workspace"]);$u->workspaces()->attach($w->id,['role'=>'owner']);Auth::login($u);return response()->json($u,201);}
 public function login(Request $r){$d=$r->validate(['email'=>'required|email','password'=>'required|string']);if(!Auth::attempt($d))return response()->json(['message'=>'Invalid credentials.'],422);$r->session()->regenerate();return response()->json($r->user());}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return response()->noContent();}
 public function redirect(string $provider){abort_unless(in_array($provider,['google','github'],true),404);abort_unless(config("services.$provider.client_id"),503,'OAuth provider is not configured.');return Socialite::driver($provider)->redirect();}
 public function callback(string $provider){abort_unless(in_array($provider,['google','github'],true),404);$p=Socialite::driver($provider)->user();$check=$this->resolveEmail($provider,$p);if($check['error']){Log::warning('OAuth sign-in rejected: '.$check['error'],['provider'=>$provider]);return redirect('/login?error='.$check['error']);}$existing=User::where('email',$check['email'])->first();if($existing&&$existing->password&&! $check['verified']){Log::warning('OAuth refused to link unverified email to a password account.',['provider'=>$provider]);return redirect('/login?error=oauth-link-denied');}$u=User::updateOrCreate(['email'=>$check['email']],['name'=>$p->getName()?:$p->getNickname()?:'DeploySift user']);if($u->workspaces()->count()===0){$w=Workspace::create(['name'=>$u->name."'s Workspace"])->fresh();$u->workspaces()->attach($w->id,['role'=>'owner']);}Auth::login($u,true);return redirect('/');}
 private function resolveEmail(string $provider,$u): array { $raw=method_exists($u,'getRaw')?(array)$u->getRaw():[]; $email=$u->getEmail()??($raw['email']??null); if(! is_string($email)||trim($email)==='')return ['email'=>null,'verified'=>false,'error'=>'oauth-no-email']; $verified=false; $explicit=false; if($provider==='google'){$verified=($raw['email_verified']??null)===true;$explicit=array_key_exists('email_verified',$raw)&&$raw['email_verified']===false;} elseif($provider==='github'){$flag=$raw['verified']??($raw['email_verified']??null);$verified=in_array($flag,[true,1,'1','true'],true);$explicit=in_array($flag,[false,0,'0','false'],true);} if($explicit)return ['email'=>$email,'verified'=>false,'error'=>'oauth-unverified']; return ['email'=>$email,'verified'=>$verified,'error'=>null]; }
}
